import React from 'react'
import Message from './Message.js'

const Messages = () => {

  state = {data: []};

  fetchData()
  {
    fetch('/data')
      .then(res => res.json())
      .then(data => this.setState({ data }));
  };

  return (
    <div className='messages'>
        <Message/>
        <Message/>
        <Message/>
        <Message/>
    </div>
  )
}

export default Messages
